import numpy as np
from scipy import stats
from sklearn.cluster import SpectralClustering
from sklearn.metrics.pairwise import cosine_similarity

MAX_DRIVERS = 5

def design(feats):
    # Filter to significant features (p < 0.05)
    sig_idx = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'expression':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==0, feats.column(fid)], feats.x[feats.y==1, feats.column(fid)])
            if p_val < 0.05:
                sig_idx.append(i)

    # If no significant features, return empty design
    if not sig_idx:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build correlation matrix
    corr_matrix = np.corrcoef(feats.x[:, sig_idx].T)
    # Mask diagonal
    np.fill_diagonal(corr_matrix, 0)

    # Find highly correlated pairs (|r| >= 0.6)
    high_corr_pairs = []
    for i in range(len(sig_idx)):
        for j in range(i+1, len(sig_idx)):
            if abs(corr_matrix[i,j]) >= 0.6:
                high_corr_pairs.append((feats.ids[sig_idx[i]], feats.ids[sig_idx[j]]))

    # Cluster features using spectral clustering based on correlation
    if len(sig_idx) > 1:
        clustering = SpectralClustering(n_clusters=min(3, len(sig_idx)), affinity='precomputed', random_state=0)
        clusters = clustering.fit_predict(1 - np.abs(corr_matrix))  # Convert to distance

        # Select cluster with highest mean effect size
        best_cluster = max(range(max(clusters)+1), key=lambda c: np.mean([np.mean(feats.x[feats.y==1, feats.column(fid)]) - np.mean(feats.x[feats.y==0, feats.column(fid)]) 
                                                                         for fid in [feats.ids[sig_idx[i]] for i in range(len(sig_idx)) if clusters[i] == c]]))

        # Get features in best cluster
        cluster_features = [feats.ids[sig_idx[i]] for i in range(len(sig_idx)) if clusters[i] == best_cluster]
    else:
        cluster_features = [feats.ids[sig_idx[0]]]

    # If we have more than one feature in cluster, consider interactions
    products = []
    if len(cluster_features) > 1:
        # Consider pairwise products between features in same cluster
        for i in range(len(cluster_features)):
            for j in range(i+1, len(cluster_features)):
                products.append((cluster_features[i], cluster_features[j]))

    # Calculate weighted loading score using first principal component
    if len(cluster_features) >= 2:
        # Use first PC of selected features as weighted score
        x_sub = feats.x[:, [feats.column(fid) for fid in cluster_features]]
        _, _, vt = np.linalg.svd(x_sub, full_matrices=False)
        weights = vt[0] / np.linalg.norm(vt[0])
        loadings = dict(zip(cluster_features, weights))
    else:
        loadings = {cluster_features[0]: 1.0}

    # Drivers are the top features by effect size
    effect_sizes = [(fid, np.mean(feats.x[feats.y==1, feats.column(fid)]) - np.mean(feats.x[feats.y==0, feats.column(fid)])) 
                    for fid in cluster_features]
    drivers = tuple(sorted(effect_sizes, key=lambda x: abs(x[1]), reverse=True))[:MAX_DRIVERS]

    return Design(
        drivers=tuple(fid for fid, _ in drivers),
        columns=cluster_features,
        products=products,
        loadings=loadings
    )

